## Why This Is Asked

Tests CGOA memory ownership, cross-language error handling, and concurrent data processing in a streaming context.

## Key Concepts

- CGO memory ownership: free allocated JSON from Go after conversion
- Translating C error codes to Go errors
- Thread-safety with concurrent CGO calls
- Streaming via a worker pool and per-block error propagation

## Code Example

```c
// header and minimal C impl
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

int block_histogram(const uint8_t* block, size_t len, char** out_json){
    if(!block || len==0) return -1;
    // simple placeholder: allocate JSON string
    char* json = (char*)malloc(64);
    if(!json) return -1;
    strcpy(json, "{\"bins\":[]}");
    *out_json = json;
    return 0;
}
```

```go
// Go binding sketch
package main
/*
#include <stdint.h>
#include <stdlib.h>
int block_histogram(const uint8_t* block, size_t len, char** out_json);
*/
import "C"
import (
    "errors"
    "unsafe"
)

func BlockHistogram(data []byte) (string, error) {
    if len(data) == 0 { return "", errors.New("empty block") }
    cptr := (*C.uint8_t)(unsafe.Pointer(&data[0]))
    var cjson *C.char
    if C.block_histogram(cptr, C.size_t(len(data)), &cjson) != 0 {
        return "", errors.New("C error")
    }
    defer C.free(unsafe.Pointer(cjson))
    return C.GoString(cjson), nil
}
```

